const { defaultPerPage, maxPerPage } = require('./config');

function clampSize(perPage) {
  return Math.min(perPage, maxPerPage);
}

function pageCount(total, perPage = defaultPerPage) {
  return Math.floor(total / clampSize(perPage));
}

function pageSlice(items, page, perPage = defaultPerPage) {
  const size = clampSize(perPage);
  const start = (page - 1) * size;
  return items.slice(start, start + size);
}

module.exports = { pageCount, pageSlice };

