const { roundToCents } = require('./money');

const BULK_MIN_QTY = 10;
const BULK_RATE = 0.05;

function subtotal(items) {
  let total = 0;
  for (const item of items) total += item.price * item.qty;
  return total;
}

function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}

function bulkDiscount(items) {
  if (itemCount(items) > BULK_MIN_QTY) {
    return roundToCents(subtotal(items) * BULK_RATE);
  }
  return 0;
}

module.exports = { subtotal, itemCount, bulkDiscount };

